Almost perfect. Inspirational.<p>It just needed to create a little box you can drag around when you click on nothing, like OS desktops have.<p>So here&#x27;s the snippet to do that, toss this in the console and live the dream:<p>(() =&gt; {
  let startX, startY, box, dragging = false;<p><pre><code>  const style = document.createElement(&#x27;style&#x27;);
  style.textContent = `
    .___selection-box {
      position: absolute;
      pointer-events: none;
      border: 1px dashed #2b76d6;
      background: rgba(43,118,214,0.12);
      z-index: 999999;
    }
  `;
  document.head.appendChild(style);

  function onDown(e) {
    if (e.button !== 0) return; &#x2F;&#x2F; left click only
    startX = e.pageX;
    startY = e.pageY;
    dragging = true;

    box = document.createElement(&#x27;div&#x27;);
    box.className = &#x27;___selection-box&#x27;;
    box.style.left = startX + &#x27;px&#x27;;
    box.style.top = startY + &#x27;px&#x27;;
    document.body.appendChild(box);

    e.preventDefault();
  }

  function onMove(e) {
    if (!dragging) return;
    const x = e.pageX, y = e.pageY;
    const left = Math.min(x, startX);
    const top = Math.min(y, startY);
    const width = Math.abs(x - startX);
    const height = Math.abs(y - startY);
    Object.assign(box.style, {
      left: left + &#x27;px&#x27;,
      top: top + &#x27;px&#x27;,
      width: width + &#x27;px&#x27;,
      height: height + &#x27;px&#x27;
    });
  }

  function onUp(e) {
    if (!dragging) return;
    dragging = false;
    console.log(&#x27;Selection rect:&#x27;, box.getBoundingClientRect());
    box.remove();
    box = null;
  }

  window.addEventListener(&#x27;mousedown&#x27;, onDown);
  window.addEventListener(&#x27;mousemove&#x27;, onMove);
  window.addEventListener(&#x27;mouseup&#x27;, onUp);

  console.log(&quot; Selection enabled. Drag with left mouse button. Check console for rect.&quot;);</code></pre>
})();

